function keyFor(app,code,down){app.events.get(down?'keydown':'keyup')({code,repeat:false,target:{matches:()=>false},preventDefault(){}});}
function skiToFinish(app,success=true){let frames=0,left=false,right=false;while(app.api.get().ski&&frames++<8000){const c=app.api.get().ski,g=skiRules.SKI_GATES[c.results.length],desired=success&&g?Math.max(-1,Math.min(1,(g.x-c.x)*3-c.vx*.6)):0,nl=desired<-.10,nr=desired>.10;if(nl!==left){keyFor(app,'ArrowLeft',nl);left=nl;}if(nr!==right){keyFor(app,'ArrowRight',nr);right=nr;}app.frames();}assert.ok(frames<8000,'ski finishes through actual frame loop');keyFor(app,'ArrowLeft',false);keyFor(app,'ArrowRight',false);}
