// Two target games through actual raycasts and UI; no direct score mutation.
async function enterTarget(app,kind,level='easy'){const file=JSON.parse(JSON.stringify(app.api.get().state)),p=targetRules.TARGET_STARTS[kind];file.position={x:p.x,z:p.z,region:p.region,inside:false};if(!file.adventure.visited.includes(p.region))file.adventure.visited.push(p.region);file.energy=100;await importGame(app,file);app.api.interact();assert.ok(app.el('modalbody').innerHTML.includes(targetRules.TARGET_NAMES[kind]));app.button('targetlevel',level).click();assert.equal(app.api.get().targetRound.kind,kind);assert.equal(app.api.get().state.energy,95);}
function clickTargetObject(app,o){const kit=app.api.get().targetKit,v=new Three.Vector3(o.x,o.y,o.z).project(kit.camera),ray=new Three.Raycaster();ray.setFromCamera(new Three.Vector2(v.x,v.y),kit.camera);const hit=ray.intersectObjects(kit.pickable())[0];if(hit?.object.userData.targetId!==o.id)return false;const e={clientX:(v.x+1)/2*1366,clientY:(1-v.y)/2*900};app.el('game').listeners.get('pointerdown')(e);app.el('game').listeners.get('pointerup')(e);return true;}
function winTarget(app){let turns=0;while(app.api.get().targetRound&&turns++<1000){const c=app.api.get().targetRound,d=targetRules.TARGET_LEVELS[c.level];if(c.countdown>0||c.cooldown>0){app.frames(22);continue;}if(c.hits>=d.goal){app.frames(100);continue;}const choices=targetRules.targetObjects(c).filter(o=>o.kind==='target'&&o.visible);let fired=false;for(const o of choices)if(clickTargetObject(app,o)){fired=true;break;}if(!fired)app.frames(12);}assert.ok(turns<1000);assert.ok(app.el('modalbody').innerHTML.includes('Challenge geschafft'));}
